export interface FlexibleAgentConfig {
    maxIterations?: number;
    analysisMode?: boolean;
    timeoutMs?: number;
    model?: string;
    temperature?: number;
    maxTokens?: number;
}
export interface FlexibleAgentContext {
    agentId: string;
    depth: number;
    sprint?: number;
    availableMemory: string[];
    [key: string]: any;
}
export type FlexibleChunkType = "thought" | "tool_call" | "tool_result" | "completion" | "error";
export interface FlexibleAgentChunk {
    type: FlexibleChunkType;
    turn?: number;
    text?: string;
    toolName?: string;
    inputCode?: string;
    toolCallId?: string;
    resultJson?: string;
    parsedResult?: any;
    dataId?: string;
    dataSize?: number;
    success?: boolean;
    errorMessage?: string;
    reason?: "llm_stopped" | "max_iterations" | "timeout" | "error";
    totalTurns?: number;
    totalToolCalls?: number;
    history?: ConversationTurn[];
    errorType?: string;
    message?: string;
    stackTrace?: string;
}
export interface ConversationTurn {
    role: "assistant" | "tool";
    content: string;
    toolName?: string;
    toolCallId?: string;
}
export interface FlexibleAgentResult {
    thoughts: Array<{
        text: string;
        turn: number;
    }>;
    toolCalls: Array<{
        name: string;
        code: string;
        callId: string;
        result: any;
        success: boolean;
        turn: number;
    }>;
    completionReason: "llm_stopped" | "max_iterations" | "timeout" | "error";
    totalTurns: number;
    totalToolCalls: number;
    lastToolResult: any | null;
    history: ConversationTurn[];
}
